async function renderTrash(){
  const box=$('#view-trash'); if(!box)return;
  box.innerHTML='<div class="empty">Loading Trash & Cleanup…</div>';
  try{
    const [cand,trash]=await Promise.all([api('/api/platform/admin/trash/candidates?limit=150'),api('/api/platform/admin/trash?limit=150')]);
    const candidates=cand.candidates||[],items=trash.items||[];
    box.innerHTML=`<div class="eyebrow">SUPER ADMIN · DATA CLEANUP</div>
    <h1 class="title">Trash & Recovery</h1>
    <p class="sub">One lifecycle boundary for quarantine, restore and permanent disposition. Trash is reversible. Permanent purge is step-up protected and only deletes records whose canonical authority confirms they are disposable; live operational truth, legal holds and committed provenance remain protected.</p>
    <section class="grid four"><article class="card stat"><span>Cleanup candidates</span><strong>${candidates.length}</strong><div class="mini">Review before moving anything</div></article><article class="card stat"><span>In Trash</span><strong>${items.length}</strong><div class="mini">Reversible quarantine</div></article><article class="card stat"><span>High-confidence</span><strong>${candidates.filter(x=>x.confidence==='high').length}</strong><div class="mini">Safe candidates still require Super Admin confirmation</div></article><article class="card stat"><span>Permanent deletion</span><strong>STEP-UP</strong><div class="mini">Dependency and legal-hold checks enforced</div></article><article class="card stat"><span>Evidence pending</span><strong>${items.filter(x=>x.evidence_status==='pending_reconciliation').length}</strong><div class="mini">Lifecycle evidence requires reconciliation</div></article></section>
    <section class="card section critical-action-bar"><div class="section-head"><div><span class="eyebrow">CRITICAL ACTION AUTHORIZATION</span><h2>Super Admin step-up</h2><p class="sub">Trash, restore and permanent purge are governed mutations. Authorize before operating on lifecycle data.</p></div><div class="actions"><button class="btn primary" id="authorizeTrash">AUTHORIZE CRITICAL ACTIONS</button><span id="trashStepUpState" class="pill warn">NOT AUTHORIZED</span></div></div></section>
    <section class="card section"><div class="section-head"><div><span class="eyebrow">CANDIDATES</span><h2>What looks like waste?</h2><p class="sub">Candidates can be reviewed individually or moved together into reversible Trash. Dependency and lifecycle rules still apply to every item.</p></div><div class="actions"><button class="btn muted" id="refreshTrash">REFRESH</button><button class="btn danger" id="trashAllCandidates">MOVE ALL CANDIDATES TO TRASH</button></div></div>
    <div class="table-wrap"><table class="table"><thead><tr><th>Record</th><th>Classification</th><th>Confidence</th><th>Reason</th><th>Dependencies</th><th>Action</th></tr></thead><tbody>${candidates.map(c=>`<tr><td><b>${esc(c.display_name)}</b><div class="mini">${esc(c.resource_type)} · ${esc(c.resource_id)}</div></td><td>${esc(c.classification)}</td><td><span class="pill ${c.confidence==='high'?'ok':c.confidence==='medium'?'warn':'bad'}">${esc(c.confidence)}</span></td><td>${esc(c.reason)}</td><td>${Number(c.dependency_count||0)}</td><td><button class="btn muted" data-trash-candidate='${esc(JSON.stringify({resourceType:c.resource_type,resourceId:c.resource_id}))}'>MOVE TO TRASH</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No cleanup candidates detected.</td></tr>'}</tbody></table></div></section>
    <section class="card section"><div class="section-head"><div><span class="eyebrow">TRASH</span><h2>Quarantined records</h2><p class="sub">Restore returns the supported record to its previous state. Purge permanently removes it only after dependency checks pass.</p></div><div class="actions"><button class="btn muted" id="reconcileTrashEvidence">RECONCILE EVIDENCE</button><button class="btn danger" id="emptyTrash">EMPTY TRASH · PURGE SAFE ITEMS</button></div></div>
    <div class="table-wrap"><table class="table"><thead><tr><th>Record</th><th>Reason</th><th>Trashed</th><th>Dependencies</th><th>Evidence</th><th>Action</th></tr></thead><tbody>${items.map(i=>`<tr><td><b>${esc(i.display_name)}</b><div class="mini">${esc(i.resource_type)} · ${esc(i.resource_id)}</div></td><td>${esc(i.reason_code)}</td><td>${esc(i.trashed_at||'—')}</td><td>${esc(JSON.stringify(i.dependencies||{}))}</td><td><span class="pill ${i.evidence_status==='pending_reconciliation'?'warn':'ok'}">${esc(i.evidence_status||'complete')}</span>${i.evidence_error_code?`<div class="mini">${esc(i.evidence_error_code)}</div>`:''}</td><td><div class="actions"><button class="btn muted" data-trash-restore="${esc(i.id)}">RESTORE</button><button class="btn danger" data-trash-purge="${esc(i.id)}">DELETE PERMANENTLY</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Trash is empty.</td></tr>'}</tbody></table></div></section>
    <section class="card section"><span class="eyebrow">LIFECYCLE RULE</span><h2>Permanent deletion is selective, not blind</h2><p class="sub">Disposable drafts, unused reference records, blocked components and non-operational identities can be permanently removed after dependency checks. Mission history, evidence, committed data-entry provenance, active products and records under legal hold are retained or blocked from purge.</p></section><section class="card section"><span class="eyebrow">SAFETY MODEL</span><h2>Reference data is not automatically treated as sample data</h2><p class="sub">Countries are shared reference data. An unused country can be proposed for cleanup, but active products, organizations, policies, launches, definitions and expansions protect it from permanent deletion. Product drafts and abandoned expansion work are more aggressively identified because their lifecycle state provides stronger evidence that they are disposable.</p></section>`;
    $('#authorizeTrash')?.addEventListener('click',async()=>{const ok=await ensureStepUp();const st=$('#trashStepUpState');if(st){st.textContent=ok?'AUTHORIZED':'NOT AUTHORIZED';st.className=`pill ${ok?'ok':'warn'}`}});
        $('#refreshTrash').onclick=()=>renderTrash();$('#reconcileTrashEvidence')?.addEventListener('click',async()=>{try{if(!await ensureStepUp())return;const r=await api('/api/platform/admin/trash/reconcile',{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{limit:150}});alert(`Evidence reconciliation: ${r.result?.reconciled||0} repaired, ${r.result?.blocked||0} still blocked.`);await renderTrash()}catch(e){alert(e.message)}});$('#trashAllCandidates').onclick=async()=>{if(!candidates.length)return;if(!confirm(`Move all ${candidates.length} cleanup candidates to Trash? Each record will still pass dependency and lifecycle checks.`))return;try{if(!await ensureStepUp())return;const r=await api('/api/platform/admin/trash/candidates/bulk',{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{limit:candidates.length}});alert(`Moved ${r.result?.moved||0} candidates to Trash. ${r.result?.blocked||0} were blocked by governance.`);await renderTrash()}catch(e){alert(e.message)}};$('#emptyTrash').onclick=async()=>{if(!items.length)return;if(!confirm(`PERMANENTLY PURGE ${items.length} records from Trash? This is irreversible and dependency/legal-hold checks remain enforced.`))return;try{if(!await ensureStepUp())return;const r=await api('/api/platform/admin/trash/empty',{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{limit:items.length}});alert(`Purged ${r.result?.purged||0} records. ${r.result?.blocked||0} remain protected.`);await renderTrash()}catch(e){alert(e.message)}};
    box.querySelectorAll('[data-trash-candidate]').forEach(b=>b.onclick=async()=>{const x=JSON.parse(b.dataset.trashCandidate);if(!confirm(`Move ${x.resourceType} ${x.resourceId} to Trash?`))return;try{if(!await ensureStepUp())return;await api('/api/platform/admin/trash',{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{...x,reasonCode:'manual_cleanup'}});await renderTrash();}catch(e){alert(e.message)}});
    box.querySelectorAll('[data-trash-restore]').forEach(b=>b.onclick=async()=>{if(!confirm('Restore this record?'))return;try{if(!await ensureStepUp())return;await api(`/api/platform/admin/trash/${b.dataset.trashRestore}/restore`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{}});await renderTrash();}catch(e){alert(e.message)}});
    box.querySelectorAll('[data-trash-purge]').forEach(b=>b.onclick=async()=>{if(!confirm('PERMANENTLY DELETE this record? This cannot be undone.'))return;try{if(!await ensureStepUp())return;await api(`/api/platform/admin/trash/${b.dataset.trashPurge}/purge`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{}});await renderTrash();}catch(e){alert(e.message)}});
  }catch(e){box.innerHTML=`<section class="card section error-state"><div class="eyebrow">TRASH ERROR</div><h2>Cleanup workspace unavailable.</h2><div class="notice">${esc(e.message||'Trash unavailable')}</div><button class="btn primary" id="retryTrash">RETRY</button></section>`;$('#retryTrash')?.addEventListener('click',renderTrash)}
}

export { renderDataControl, renderDataEntry, renderTrash };
